add("P-RODCKrbtgtOrphan", "Сирота krbtgt RODC", "У контроллера только для чтения осталась осиротевшая учетная запись krbtgt. Удалите ее после вывода сервера.")
add("P-RODCNeverReveal", "Never reveal", "Политика RODC не запрещает раскрывать важные учетные записи. Заполните список «никогда не раскрывать».")
add("P-RODCRevealOnDemand", "Раскрытие по запросу", "На RODC включено раскрытие паролей по запросу шире, чем нужно. Оставьте только учетные записи этой площадки.")
add("P-RODCSYSVOLWrite", "Запись SYSVOL с RODC", "С контроллера только для чтения можно писать в SYSVOL. Снимите это право.")
add("P-RecoveryModeUnprotected", "Режим восстановления", "Пароль режима восстановления каталога не защищен регламентом или хранится слабо. Задайте новый и положите его в сейф, не в отчет.")
add("P-RecycleBin", "Корзина выключена", "Корзина Active Directory не включена. Включите ее один раз на лес, это необратимо и требует достаточный режим работы.")
add("P-SchemaAdmin", "Админы схемы", "В Schema Admins кто-то состоит постоянно. После изменения схемы группу нужно опустошать.")
add("P-ServiceDomainAdmin", "Служба в Domain Admins", "Служебная запись входит в администраторы домена. Вынесите ее и переведите службу на gMSA.")
add("P-TrustedCredManAccessPrivilege", "Доступ к диспетчеру учетных данных", "Привилегия чтения диспетчера учетных данных выдана лишним. Оставьте ее только системе и администраторам, которым она нужна по задаче.")
add("P-UnconstrainedDelegation", "Неограниченное делегирование", "На компьютере, который не является контроллером, включено неограниченное делегирование. Снимите флаг. Контроллеры не трогайте.")
add("P-UnkownDelegation", "Непонятное делегирование", "Флаги делегирования не распознаны как штатные. Откройте карточку компьютера и оставьте только документированное ограниченное делегирование.")
add("P-UnprotectedOU", "Подразделение без защиты", "Важное подразделение не защищено от случайного удаления. Включите защиту.")

# Устаревшее
add("S-ADRegistration", "Саморегистрация в домен", "Обычный пользователь может вводить компьютеры в домен сверх нормы. Поставьте ms-DS-MachineAccountQuota в 0 и заведите отдельное право для поддержки.")
add("S-ADRegistrationSchema", "Регистрация через схему", "Право вводить компьютеры задано слишком широко на контейнере. Сузьте создание объектов computer.")
add("S-DCRegistration", "Регистрация контроллера", "Есть признаки, что контроллер зарегистрирован нештатно. Сверьте список контроллеров с реальными серверами и уберите лишний объект.")
add("S-AesNotEnabled", "Нет AES", "Для Kerberos не включены AES128 и AES256. Включите их в параметре типов шифрования и на учетных записях.")
add("S-DC-NotUpdated", "Контроллер без обновлений", "Контроллер давно не обновлялся. Поставьте накопительные обновления в окно работ.")
add("S-DC-SubnetMissing", "Контроллер без подсети", "Контроллер не привязан к сайту и подсети. Добавьте подсеть в сайты и службы, иначе клиенты ходят не на ближайший контроллер.")
add("S-DefaultOUChanged", "Чужое подразделение по умолчанию", "Новые компьютеры или пользователи попадают не в стандартный контейнер, и политика может их не накрывать. Проверьте redircmp и redirusr.")
add("S-DefenderASR", "Нет правил ASR", "Не включены правила сокращения поверхности атак Defender. Включите их сначала в аудите, потом в блоке.")
add("S-DesEnabled", "Включен DES", "У записей разрешен DES. Оставьте AES и снимите DES в типах шифрования.")
add("S-Duplicate", "Дубликаты объектов", "В каталоге есть конфликты репликации или дубликаты. Разберите контейнер LostAndFound и конфликтующие объекты.")
add("S-FolderOptions", "Опасные параметры папок", "Политика ослабляет показ и запуск файлов в оболочке. Верните стандартные параметры проводника.")
add("S-Inactive", "Спящие пользователи", "Слишком много включенных записей давно не входили. Отключайте их после сверки с владельцем, не удаляйте в тот же день.")
add("S-C-Inactive", "Спящие компьютеры", "Много компьютеров давно не являлись в домен. Отключите и затем удалите только после инвентаризации.")
add("S-DC-Inactive", "Молчит контроллер", "Контроллер давно не реплицировался или не входил. Либо почините репликацию, либо корректно понизьте роль сервера.")
add("S-JavaSchema", "Схема Java", "В схеме осталось расширение старой Java. Удаляйте его только по проекту, если оно больше не используется приложениями.")
add("S-KerberosArmoring", "Нет FAST", "Гибкая защита Kerberos (armoring) не включена. Включайте ее после проверки, что клиенты ее понимают.")
add("S-KerberosArmoringDC", "Контроллер без FAST", "Контроллер не предлагает гибкую защиту Kerberos. Включите поддержку на контроллерах, затем требование на клиентах.")
add("S-Vuln-MS14-068", "MS14-068", "Контроллер не закрыт от старой ошибки проверки билета. Установите обновление и поднимите функциональный уровень выше уязвимого.")
add("S-Vuln-MS17_010", "MS17-010", "Есть след незакрытой ошибки SMBv1. Установите обновление и отключите SMBv1. Это не инструкция по использованию ошибки.")
add("S-NoPreAuth", "Без предварительной проверки", "У записей выключена предварительная проверка Kerberos. Включите ее обратно. Билет платформа не запрашивает.")
add("S-NoPreAuthAdmin", "Админ без предварительной проверки", "Флаг стоит на привилегированной записи. Снимите его немедленно и смените пароль.")
add("S-OS-2000", "Windows 2000", "В домене есть Windows 2000. Выведите систему из домена и замените ее.")
add("S-OS-2003", "Windows 2003", "Есть Windows Server 2003 или аналог. Замените сервер, обновлений для него больше нет.")
add("S-OS-2008", "Windows 2008", "Есть Windows Server 2008 или 2008 R2 без поддержки. Запланируйте замену.")
add("S-OS-2012", "Windows 2012", "Есть Windows Server 2012 или 2012 R2. Готовьте переход на поддерживаемый выпуск.")
add("S-DC-2000", "Контроллер 2000", "Роль контроллера на Windows 2000. Такой контроллер нужно понизить и выключить.")
add("S-DC-2003", "Контроллер 2003", "Контроллер на Windows 2003. Перенесите роли FSMO и понизьте сервер.")
add("S-DC-2008", "Контроллер 2008", "Контроллер на Windows 2008. Запланируйте новый контроллер на поддерживаемой версии.")
add("S-DC-2012", "Контроллер 2012", "Контроллер на Windows 2012. Готовьте замену, пока есть окно.")
add("S-FunctionalLevel1", "Старый режим леса", "Режим работы домена или леса слишком старый и держит слабую криптографию. Поднимайте его только после ухода старых контроллеров.")
add("S-FunctionalLevel3", "Режим ниже рекомендуемого", "Режим работы отстает от парка контроллеров. Поднимите его, когда все контроллеры это позволяют.")
add("S-FunctionalLevel4", "Режим можно поднять", "Режим работы еще не максимальный для ваших контроллеров. Поднимите после проверки приложений.")
add("S-OS-NT", "Windows NT", "В каталоге осталась система поколения NT. Удалите учетную запись компьютера после проверки, что сервера уже нет.")
add("S-OS-Vista", "Windows Vista", "Есть Windows Vista. Замените рабочие места.")
add("S-OS-W10", "Много Windows 10", "Доля Windows 10 выше порога. Составьте план перехода на поддерживаемый выпуск.")
add("S-OS-Win7", "Windows 7", "Есть Windows 7. Замените системы, если нет официальной платной поддержки.")
add("S-OS-Win8", "Windows 8", "Есть Windows 8 или 8.1. Включите их в план замены.")
add("S-OS-XP", "Windows XP", "Есть Windows XP. Выведите их из домена.")
add("S-OldNtlm", "Старый NTLM", "Разрешен LM или NTLMv1. Поставьте уровень проверки подлинности «только NTLMv2».")
add("S-PrimaryGroup", "Чужая основная группа", "У пользователя основная группа не Domain Users. Верните основную группу, исключив документированные случаи.")
add("S-C-PrimaryGroup", "Чужая группа компьютера", "У компьютера основная группа не Domain Computers. Верните ее.")
add("S-PwdLastSet-45", "Пароль старше 45 дней у служебных", "Есть записи, чей пароль не менялся, хотя политика этого ждет. Для людей включите срок, для служб переходите на gMSA.")
add("S-PwdLastSet-90", "Пароль старше 90 дней", "Пароли не менялись дольше 90 дней. Включите максимальный срок для людей.")
add("S-PwdLastSet-Cluster", "Пароль кластера", "Учетная запись кластера давно не меняла пароль. Смените ее по регламенту кластера, не вручную вразрез со службой.")
add("S-PwdLastSet-DC", "Пароль контроллера", "Пароль компьютера контроллера давно не менялся. Проверьте, что смена пароля компьютера не запрещена и репликация жива.")
add("S-PwdNeverExpires", "Пароль не истекает", "Слишком много записей с вечным паролем. Снимите флаг у людей. Службы переведите на gMSA.")
add("S-PwdNotRequired", "Пароль не требуется", "У включенной записи не требуется пароль. Снимите флаг и задайте пароль.")
add("S-Reversible", "Обратимый пароль у людей", "У пользователей включено обратимое шифрование пароля. Выключите флаг и смените пароль.")
add("S-C-Reversible", "Обратимый пароль компьютера", "У компьютера включено обратимое шифрование. Снимите флаг.")
add("S-SIDHistory", "История SID", "В атрибуте истории SID остались чужие идентификаторы после миграции. Очищайте их только после проверки, что доступ уже перенесен. Не добавляйте туда SID вручную.")
add("S-SMB-v1", "SMBv1", "В домене еще включен SMBv1. Отключите серверный компонент и драйвер клиента, затем перезагрузите. Подробный порядок есть в проверках платформы.")
add("S-FirewallScript", "Сценарий ходит наружу", "Сценарий политики обращается в интернет. Уберите внешний адрес, оставьте только внутренний источник.")
add("S-TerminalServicesGPO", "Удаленный рабочий стол", "Политика удаленных рабочих столов ослаблена: слабое шифрование или слишком широкий доступ. Оставьте NLA и согласованную группу доступа.")
add("S-WSUS-NoPinning", "WSUS без привязки", "Клиент обновлений не закреплен за своим сервером. Задайте адрес WSUS политикой и запретите чужой сервер.")
add("S-WSUS-UserProxy", "Прокси обновлений от пользователя", "Параметры прокси обновлений можно подменить пользовательской политикой. Зафиксируйте их в политике компьютера.")
add("S-WSUS-HTTP", "WSUS по HTTP", "Обновления качаются по HTTP. Переведите WSUS на HTTPS, иначе подмену пакетов не заметить.")

# Доверия
add("T-AlgsAES", "Доверие без AES", "Доверие не использует AES. Включите AES на свойствах доверия, когда оба домена это умеют.")
add("T-AzureADSSO", "Ключ Azure SSO", "Ключ единого входа с облаком давно не менялся. Ротируйте его по регламенту Azure AD Connect, ключ в отчет не копируйте.")
add("T-Downlevel", "Старое доверие", "Доверие использует устаревший протокол. Пересоздайте его на современном типе после согласования с соседним доменом.")
add("T-FileDeployedOutOfDomain", "Файл из чужого домена", "Политика запускает файл из другого домена. Перенесите файл к себе.")
add("T-Inactive", "Мертвое доверие", "Доверием давно никто не пользуется. Удалите его, если соседний домен подтвердит.")
add("T-ScriptOutOfDomain", "Сценарий из чужого домена", "Сценарий входа лежит в другом домене. Перенесите его в свой SYSVOL.")
add("T-SIDFiltering", "Нет фильтрации SID", "На доверии выключена фильтрация SID. Включите карантин. Подделывать SID нельзя и незачем: задача — не принимать чужие идентификаторы.")
add("S-Domain$$$", "Группа аудита истории SID", "Не настроена группа, через которую видно появление опасной истории SID. Создайте штатную группу аудита и включите ее контроль.")
add("T-SIDHistoryDangerous", "Опасная история SID", "В истории SID есть идентификатор привилегированной группы. Удалите этот SID из атрибута после сверки миграции. Не добавляйте новые.")
add("T-SIDHistorySameDomain", "История SID своего домена", "В истории SID лежит идентификатор этого же домена. Очистите атрибут: так обходят членство в группах.")
add("T-SIDHistoryUnknownDomain", "История SID неизвестного домена", "В истории SID есть домен, с которым нет понятного доверия. Разберите миграцию и очистите атрибут.")
add("T-TGTDelegation", "Делегирование билета по доверию", "По доверию разрешено делегировать билет пользователя. Выключите делегирование TGT на внешнем доверии, если оно не требуется явно.")

