def split_explain(text: str) -> tuple[str, str]:
    parts = [part.strip().rstrip(".") for part in text.split(". ") if part.strip()]
    if len(parts) < 2:
        return text, text
    return parts[0] + ".", " ".join(part + "." for part in parts[1:])


def rule_model(tail: str) -> tuple[str, str]:
    models = {
        "TriggerOnPresence": "срабатывает, если условие найдено",
        "TriggerOnThreshold": "набирает вес после заданного порога",
        "TriggerIfLessThan": "срабатывает, если значение ниже порога",
        "PerDiscover": "добавляет баллы за каждый найденный объект",
        "PerDiscoverWithAMinimumOf": "добавляет баллы за каждый объект после минимума",
    }
    name = "проверяет условие отчета"
    for key, phrase in models.items():
        if key in tail:
            name = phrase
            break
    numbers = [piece for piece in tail.replace(",", " ").split() if piece.isdigit()]
    points = numbers[0] if numbers else "0"
    return name, points


def pack(group, rule_id, title, family, text, what, sev="medium"):
    impact, fix = split_explain(text)
    return {
        "g": group,
        "id": rule_id,
        "title": title,
        "family": family,
        "text": text,
        "what": what,
        "impact": impact,
        "fix": fix,
        "sev": sev,
    }


def points_sev(points: str) -> str:
    try:
        weight = int(points)
    except ValueError:
        return "low"
    if weight >= 30:
        return "critical"
    if weight >= 15:
        return "high"
    if weight >= 5:
        return "medium"
    return "low"


