def main():
    rules = []
    for line in (ROOT / "_pc_rules.txt").read_text(encoding="utf-8").splitlines():
        parts = line.split("\t")
        rule_id, category = parts[0], parts[1]
        if rule_id == "?":
            continue
        if rule_id not in TEXT:
            raise SystemExit("no text for " + rule_id)
        title, text = TEXT[rule_id]
        tail = parts[4] if len(parts) > 4 else ""
        model, points = rule_model(tail)
        what = f"Код {rule_id}, раздел «{FAMILY[category]}». Правило {model}. Вес в индексе PingCastle: {points}."
        rules.append(pack("pingcastle", rule_id, title, FAMILY[category], text, what, points_sev(points)))
    missing = sorted(set(TEXT) - {item["id"] for item in rules})
    if missing:
        raise SystemExit("extra " + ",".join(missing))
    items = [pack(g, i, t, "Общее", x, x) for g, i, t, x in PLATFORM]
    items += [pack(g, i, t, "Общее", x, x) for g, i, t, x in BLOOD]
    items += [
        {
            "g": "platform",
            "id": rule_id,
            "title": title,
            "family": family,
            "text": what + " " + impact + " " + fix,
            "what": what,
            "impact": impact,
            "fix": fix,
            "sev": sev,
        }
        for rule_id, title, family, sev, what, impact, fix in SURFACE
    ]
    items += rules
    payload = "window.BROSEC_WIKI = " + json.dumps(items, ensure_ascii=False, indent=2) + ";\n"
    (ROOT / "app" / "static" / "wiki.js").write_text(payload, encoding="utf-8")
    print("items", len(items), "pingcastle", len(rules))


if __name__ == "__main__":
    main()
